// requirement: REQ-1.1
import { test, expect } from '@playwright/test';
import { enter } from './helpers';

test("REQ-1.1: Open the book workspace", async ({ page }) => {
  await enter(page);
  await expect(page.getByRole('link', { name: 'Books', exact: true })).toBeVisible();
  await page.getByRole('link', { name: 'Books', exact: true }).click();
  await expect(page.getByRole('region', { name: 'Book list', exact: true })).toBeVisible();
});

// requirement: REQ-2.1
import { test, expect } from '@playwright/test';
import { identity, enter, region, entry, go, createBook } from './helpers';

test("REQ-2.1: Show a uniquely identified item", async ({ page }, testInfo) => {
  const id = identity(testInfo);
  await enter(page);
  const name = await createBook(page, id, 'Book 5.1');
  await go(page, 'Books');
  await expect(entry(region(page, 'Book list'), name)).toHaveCount(1);
});

// requirement: REQ-2.2
import { test } from '@playwright/test';
import { text, identity, enter, heading, createBook, openBook } from './helpers';

test("REQ-2.2: Open from global list", async ({ page }, testInfo) => {
  const id = identity(testInfo);
  await enter(page);
  const name = await createBook(page, id, 'Book 5.2.1');
  await openBook(page, name);
  await heading(page, name);
  await text(page, 'Reference book description.');
});

// requirement: REQ-2.3
import { test, expect } from '@playwright/test';
import { identity, named, enter, region, entry, button, heading, text, metadata, beginBook, createBook } from './helpers';

test("REQ-2.3: Save a new book", async ({ page }, testInfo) => {
  const id = identity(testInfo);
  await enter(page);
  const name = await createBook(page, id, 'Book Created 5.3.1', 'Book created by corresponding prerequisite behavior.', 'created, book');
  await heading(page, name);
  await text(page, 'Book created by corresponding prerequisite behavior.');
  await page.reload();
  await button(page, 'Edit').click();
});

test("REQ-2.3: Cancel new book", async ({ page }, testInfo) => {
  const id = identity(testInfo);
  await enter(page);
  await beginBook(page);
  const name = named(id, 'Book Cancelled 5.3.2');
  await metadata(page, name, 'Unsaved book description 5.3.2.', 'cancelled, book');
  await button(page, 'Cancel').click();
  await heading(page, 'Books');
  await expect(entry(region(page, 'Book list'), name)).toHaveCount(0);
});

// requirement: REQ-2.4
import { test, expect } from '@playwright/test';
import { identity, named, enter, button, heading, text, metadata, createBook, openBook } from './helpers';

test("REQ-2.4: Save metadata changes", async ({ page }, testInfo) => {
  const id = identity(testInfo);
  await enter(page);
  const original = await createBook(page, id, 'Book 5.4.1', 'Reference book description.', 'manual, handbook');
  await openBook(page, original);
  await button(page, 'Edit').click();
  const updated = named(id, 'Book Updated 5.4.1');
  await metadata(page, updated, 'Book updated by corresponding prerequisite behavior.', 'manual, handbook');
  await button(page, 'Save Book').click();
  await heading(page, updated);
  await text(page, 'Book updated by corresponding prerequisite behavior.');
  await page.reload();
  await heading(page, updated);
  await text(page, 'Book updated by corresponding prerequisite behavior.');
  await button(page, 'Edit').click();
});

test("REQ-2.4: Cancel metadata changes", async ({ page }, testInfo) => {
  const id = identity(testInfo);
  await enter(page);
  const original = await createBook(page, id, 'Book 5.4.2', 'Reference book description.', 'manual, handbook');
  await openBook(page, original);
  await button(page, 'Edit').click();
  const updated = named(id, 'Book Updated 5.4.2');
  await metadata(page, updated, 'Book updated by corresponding prerequisite behavior.', 'manual, handbook');
  await button(page, 'Cancel').click();
  await heading(page, original);
  await text(page, 'Reference book description.');
  await expect(page.getByRole('heading', { name: updated, exact: true })).toHaveCount(0);
});

// requirement: REQ-2.5
import { test, expect } from '@playwright/test';
import { identity, enter, region, entry, button, heading, text, go, createBook, openBook } from './helpers';

test("REQ-2.5: Confirm deletion", async ({ page }, testInfo) => {
  const id = identity(testInfo);
  await enter(page);
  const name = await createBook(page, id, 'Book 5.5.1', 'Reference book description.');
  await openBook(page, name);
  await button(page, 'Delete').click();
  await button(page, 'Confirm Delete').click();
  await heading(page, 'Books');
  await page.reload();
  await go(page, 'Books');
  await expect(entry(region(page, 'Book list'), name)).toHaveCount(0);
});

test("REQ-2.5: Cancel deletion", async ({ page }, testInfo) => {
  const id = identity(testInfo);
  await enter(page);
  const name = await createBook(page, id, 'Book 5.5.2', 'Reference book description.');
  await openBook(page, name);
  await button(page, 'Delete').click();
  await button(page, 'Cancel').click();
  await heading(page, name);
  await text(page, 'Reference book description.');
});

// requirement: REQ-3.1
import { test, expect } from '@playwright/test';
import { identity, enter, region, entry, heading, createBook, createPage } from './helpers';

